export type GameIconName = keyof typeof PATHS

type GameIconProps = Omit<React.SVGProps<SVGSVGElement>, "name"> & { size?: number | string }

export function GameIcon({ name, size = 24, ...props }: GameIconProps & { name: GameIconName }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 512 512"
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
      {...props}
    >
      <path d={PATHS[name]} />
    </svg>
  )
}

/** One icon as a component of its own, for maps of icons such as a navigation's. */
export function gameIcon(name: GameIconName) {
  return function GameIconMark(props: GameIconProps) {
    return <GameIcon {...props} name={name} />
  }
}
